"""Чистые парсеры ответов Metacritic: JSON -> модели. Без сети и без БД.

Все функции терпимы к «дырам» в выдаче: Metacritic регулярно отдаёт `null`,
пустые строки и отсутствующие блоки вместо честного отсутствия поля.
"""

from __future__ import annotations

import datetime as dt
import re
from typing import Any

from app.metacritic.schemas import (
    FinderItem,
    GameDetail,
    PlatformInfo,
    ReviewItem,
    ScoreStats,
)

IMAGE_BASE = "https://www.metacritic.com/a/img"
SITE_BASE = "https://www.metacritic.com"
JWPLAYER_EMBED = "https://cdn.jwplayer.com/players/{jw_id}.html"

# Порядок предпочтения обложки в деталке: cardImage — вертикальный постер, mainImage — кадр.
_COVER_PRIORITY = ("cardImage", "mainImage")

_SLUG_RE = re.compile(r"[^a-z0-9]+")


def slugify(value: str | None) -> str | None:
    """Приводит человекочитаемое имя платформы к слагу Metacritic ("PlayStation 5" -> "playstation-5")."""
    if not value:
        return None
    slug = _SLUG_RE.sub("-", value.strip().lower()).strip("-")
    return slug or None


def parse_date(value: Any) -> dt.date | None:
    """Дата из выдачи: 'YYYY-MM-DD', ISO-8601 с временем, пустая строка, null или вложенный dict."""
    if value is None:
        return None
    if isinstance(value, dt.datetime):
        return value.date()
    if isinstance(value, dt.date):
        return value
    if isinstance(value, dict):  # displayDatePublished и подобные обёртки
        return parse_date(value.get("date"))
    if not isinstance(value, str):
        return None
    raw = value.strip()
    if not raw:
        return None
    try:
        return dt.date.fromisoformat(raw[:10])
    except ValueError:
        pass
    try:
        return dt.datetime.fromisoformat(raw.replace("Z", "+00:00")).date()
    except ValueError:
        return None


def _as_int(value: Any) -> int | None:
    if value is None or isinstance(value, bool):
        return None
    try:
        return int(round(float(value)))
    except (TypeError, ValueError):
        return None


def _as_float(value: Any) -> float | None:
    if value is None or isinstance(value, bool):
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _clean(value: Any) -> str | None:
    """Пустая строка в выдаче означает «нет значения» — приводим её к None."""
    if not isinstance(value, str):
        return None
    text = value.strip()
    return text or None


def build_image_url(image: dict[str, Any] | None) -> str | None:
    """Абсолютный URL картинки из пары bucketType + bucketPath.

    Готового URL в выдаче нет: `imageUrl` всегда null, склейка обязательна.
    """
    if not isinstance(image, dict):
        return None
    direct = _clean(image.get("imageUrl"))
    if direct:
        return direct if direct.startswith("http") else f"{SITE_BASE}{direct}"
    bucket_type = _clean(image.get("bucketType"))
    bucket_path = _clean(image.get("bucketPath"))
    if not bucket_type or not bucket_path:
        return None
    if not bucket_path.startswith("/"):
        bucket_path = f"/{bucket_path}"
    return f"{IMAGE_BASE}/{bucket_type}{bucket_path}"


def _pick_cover(item: dict[str, Any]) -> str | None:
    """Обложка деталки: сначала постер (cardImage), потом кадр, потом что нашлось."""
    images = item.get("images")
    if isinstance(images, list) and images:
        by_type = {
            _clean(img.get("typeName")): img
            for img in images
            if isinstance(img, dict)
        }
        for type_name in _COVER_PRIORITY:
            url = build_image_url(by_type.get(type_name))
            if url:
                return url
        for img in images:
            url = build_image_url(img if isinstance(img, dict) else None)
            if url:
                return url
    return build_image_url(item.get("image"))


def _genre_names(raw: Any) -> list[str]:
    if not isinstance(raw, list):
        return []
    names: list[str] = []
    for genre in raw:
        name = _clean(genre.get("name")) if isinstance(genre, dict) else _clean(genre)
        if name and name not in names:
            names.append(name)
    return names


def _company(production: Any, type_name: str) -> str | None:
    """Разработчик/издатель из production.companies по typeName (может быть несколько — берём первого)."""
    if not isinstance(production, dict):
        return None
    companies = production.get("companies")
    if not isinstance(companies, list):
        return None
    for company in companies:
        if not isinstance(company, dict):
            continue
        if (company.get("typeName") or "").strip().lower() == type_name.lower():
            name = _clean(company.get("name"))
            if name:
                return name
    return None


def parse_score_stats(raw: Any) -> ScoreStats | None:
    """ScoreStats из criticScoreSummary или из data.item эндпоинта user-stats."""
    if isinstance(raw, dict) and "item" in raw:  # допускаем передачу целого конверта
        raw = raw["item"]
    if isinstance(raw, dict) and "data" in raw:
        raw = (raw.get("data") or {}).get("item")
    if not isinstance(raw, dict):
        return None
    score = _as_float(raw.get("score"))
    review_count = _as_int(raw.get("reviewCount"))
    sentiment = _clean(raw.get("sentiment"))
    if score is None and review_count is None and sentiment is None:
        return None
    return ScoreStats(score=score, review_count=review_count, sentiment=sentiment)


def _unwrap_item(raw: dict[str, Any]) -> dict[str, Any]:
    """Позволяет передавать как сам объект, так и конверт {"data": {"item": ...}}."""
    data = raw.get("data")
    if isinstance(data, dict) and isinstance(data.get("item"), dict):
        return data["item"]
    item = raw.get("item")
    if isinstance(item, dict):
        return item
    return raw


def parse_finder_item(raw: dict[str, Any]) -> FinderItem:
    """Элемент listing-выдачи finder-а (карусель и browse отдают одинаковую форму)."""
    critic = raw.get("criticScoreSummary")
    metascore = _as_int(critic.get("score")) if isinstance(critic, dict) else None
    return FinderItem(
        mc_id=int(raw["id"]),
        slug=str(raw["slug"]),
        title=_clean(raw.get("title")) or str(raw["slug"]),
        release_date=parse_date(raw.get("releaseDate")),
        description=_clean(raw.get("description")),
        cover_url=build_image_url(raw.get("image")),
        metascore=metascore,
        genres=_genre_names(raw.get("genres")),
    )


def parse_platform(raw: dict[str, Any]) -> PlatformInfo:
    name = _clean(raw.get("name")) or "Unknown"
    slug = _clean(raw.get("slug")) or slugify(name) or "unknown"
    return PlatformInfo(
        mc_id=_as_int(raw.get("id")),
        name=name,
        slug=slug,
        is_lead=bool(raw.get("isLeadPlatform")),
        release_date=parse_date(raw.get("releaseDate")),
        metascore=parse_score_stats(raw.get("criticScoreSummary")),
    )


def parse_game_detail(raw: dict[str, Any]) -> GameDetail:
    """Деталка игры. Принимает как `data.item`, так и весь ответ целиком."""
    item = _unwrap_item(raw)
    platforms = [
        parse_platform(platform)
        for platform in (item.get("platforms") or [])
        if isinstance(platform, dict)
    ]

    video = item.get("video") if isinstance(item.get("video"), dict) else {}
    trailer_url = _clean(video.get("embedUrl"))
    if not trailer_url:
        jw_id = _clean(video.get("jwPlayerId"))
        # embedUrl иногда пустой, хотя проигрыватель есть — собираем ссылку сами
        trailer_url = JWPLAYER_EMBED.format(jw_id=jw_id) if jw_id else None

    lead_metascore = None
    top_summary = parse_score_stats(item.get("criticScoreSummary"))
    if top_summary is not None:
        lead_metascore = _as_int(top_summary.score)
    if lead_metascore is None:
        for platform in platforms:
            if platform.is_lead and platform.metascore is not None:
                lead_metascore = _as_int(platform.metascore.score)
                break

    return GameDetail(
        mc_id=int(item["id"]),
        slug=str(item["slug"]),
        title=_clean(item.get("title")) or str(item["slug"]),
        description=_clean(item.get("description")),
        developer=_company(item.get("production"), "Developer"),
        publisher=_company(item.get("production"), "Publisher"),
        release_date=parse_date(item.get("releaseDate")) or parse_date(item.get("releaseDateText")),
        esrb_rating=_clean(item.get("rating")),
        genres=_genre_names(item.get("genres")),
        cover_url=_pick_cover(item),
        trailer_embed_url=trailer_url,
        trailer_title=_clean(video.get("videoTitle")) or _clean(video.get("title")),
        platforms=platforms,
        lead_metascore=lead_metascore,
    )


def _review_platform_slug(raw: dict[str, Any]) -> str | None:
    """Платформа отзыва: строкой в `platform`, либо в reviewedProduct.platform.name."""
    slug = slugify(_clean(raw.get("platform")))
    if slug:
        return slug
    product = raw.get("reviewedProduct")
    if isinstance(product, dict):
        platform = product.get("platform")
        if isinstance(platform, dict):
            return slugify(_clean(platform.get("name")))
    return None


def parse_critic_review(raw: dict[str, Any]) -> ReviewItem:
    """Отзыв критика. Своего `id` у него нет — ключ собираем из издания, автора и даты."""
    publication_slug = _clean(raw.get("publicationSlug")) or slugify(raw.get("publicationName")) or ""
    author_raw = raw.get("author") or ""
    date_raw = raw.get("date") or ""
    source_key = f"{publication_slug}:{author_raw}:{date_raw}"[:255]
    return ReviewItem(
        source_key=source_key,
        kind="critic",
        score=_as_int(raw.get("score")),
        quote=_clean(raw.get("quote")),
        author=_clean(raw.get("author")),
        publication=_clean(raw.get("publicationName")),
        review_date=parse_date(raw.get("date")),
        external_url=_clean(raw.get("url")),
        platform_slug=_review_platform_slug(raw),
        spoiler=False,
    )


def parse_user_review(raw: dict[str, Any]) -> ReviewItem:
    """Отзыв пользователя. У него есть стабильный uuid — он и есть source_key."""
    source_key = _clean(raw.get("id"))
    if not source_key:  # подстраховка: без ключа строка не пройдёт UPSERT
        source_key = f"{_clean(raw.get('author')) or 'anon'}:{raw.get('date') or ''}"
    return ReviewItem(
        source_key=source_key[:255],
        kind="user",
        score=_as_int(raw.get("score")),
        quote=_clean(raw.get("quote")),
        author=_clean(raw.get("author")),
        publication=None,
        review_date=parse_date(raw.get("date")),
        external_url=None,
        platform_slug=_review_platform_slug(raw),
        spoiler=bool(raw.get("spoiler")),
    )

"""HTTP-маршруты веб-интерфейса.

Страницы рендерятся на сервере и полностью работают без JavaScript;
HTMX только подменяет сетку карточек без перезагрузки, а SSE оживляет монитор.
"""

from __future__ import annotations

import asyncio
import contextlib
import datetime as dt
import decimal
import json
import re
import secrets
import time
from collections.abc import AsyncIterator
from pathlib import Path
from typing import Any
from urllib.parse import urlencode

import structlog
from arq.connections import ArqRedis, RedisSettings, create_pool
from fastapi import APIRouter, HTTPException, Query, Request
from fastapi.responses import FileResponse, HTMLResponse, JSONResponse
from fastapi.templating import Jinja2Templates
from sqlalchemy.ext.asyncio import AsyncSession
from sse_starlette.sse import EventSourceResponse, ServerSentEvent

from app.config import settings
from app.db.models import Game
from app.db.session import SessionLocal
from app.web.queries import (
    SORTS,
    dashboard_stats,
    get_game_by_slug,
    get_similar,
    list_games,
    normalize_sort,
    platform_facets,
)

log = structlog.get_logger(__name__)

BASE_DIR = Path(__file__).resolve().parent
TEMPLATES_DIR = BASE_DIR / "templates"
STATIC_DIR = BASE_DIR / "static"

EVENTS_CHANNEL = "metapulse:events"
WORKER_KEY_PREFIX = "metapulse:worker:"
SNAPSHOT_INTERVAL_S = 3.0
SSE_PING_S = 15
PER_PAGE = 24

# Имя файла лога: только дата и расширение. Всё остальное — попытка выйти из каталога.
LOG_NAME_RE = re.compile(r"^[A-Za-z0-9._-]+\.jsonl$")

router = APIRouter()


# --------------------------------------------------------------------------- #
# Шаблоны и фильтры
# --------------------------------------------------------------------------- #

templates = Jinja2Templates(directory=str(TEMPLATES_DIR))


def _as_float(value: Any) -> float | None:
    if value is None:
        return None
    if isinstance(value, decimal.Decimal):
        return float(value)
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def score_class(value: Any, scale: int = 100) -> str:
    """Цвет бейджа: >=75 зелёный, 50-74 жёлтый, <50 красный, нет данных — серый."""
    num = _as_float(value)
    if num is None:
        return "na"
    normalized = num * 10 if scale == 10 else num
    if normalized >= 75:
        return "good"
    if normalized >= 50:
        return "mid"
    return "bad"


def fmt_metascore(value: Any) -> str:
    num = _as_float(value)
    return "—" if num is None else str(int(round(num)))


def fmt_userscore(value: Any) -> str:
    num = _as_float(value)
    return "—" if num is None else f"{num:.1f}"


def fmt_date(value: Any) -> str:
    if isinstance(value, dt.datetime):
        return value.astimezone(settings.tz).strftime("%d.%m.%Y %H:%M")
    if isinstance(value, dt.date):
        return value.strftime("%d.%m.%Y")
    return "—"


def fmt_int(value: Any) -> str:
    num = _as_float(value)
    if num is None:
        return "—"
    return f"{int(num):,}".replace(",", " ")


def genre_names(value: Any) -> list[str]:
    """genres в БД — JSONB: пайплайн может положить и список строк, и список объектов."""
    if not value:
        return []
    names: list[str] = []
    for item in value:
        if isinstance(item, dict):
            name = item.get("name") or item.get("title") or item.get("slug")
            if name:
                names.append(str(name))
        elif item:
            names.append(str(item))
    return names


def summary_of(game: Game, kind: str) -> Any:
    for summary in game.summaries or []:
        if summary.kind == kind:
            return summary
    return None


templates.env.filters["score_class"] = score_class
templates.env.filters["metascore"] = fmt_metascore
templates.env.filters["userscore"] = fmt_userscore
templates.env.filters["date_ru"] = fmt_date
templates.env.filters["int_ru"] = fmt_int
templates.env.filters["genres"] = genre_names
templates.env.globals["summary_of"] = summary_of
templates.env.globals["SORTS"] = SORTS


# --------------------------------------------------------------------------- #
# Инфраструктурные помощники
# --------------------------------------------------------------------------- #

_arq_lock = asyncio.Lock()


def get_redis(request: Request) -> Any:
    """Redis-пул из lifespan. None означает «Redis недоступен» — не повод падать."""
    return getattr(request.app.state, "redis", None)


async def get_arq_pool(request: Request) -> ArqRedis:
    pool = getattr(request.app.state, "arq", None)
    if pool is not None:
        return pool
    async with _arq_lock:
        pool = getattr(request.app.state, "arq", None)
        if pool is None:
            pool = await create_pool(RedisSettings.from_dsn(settings.redis_url))
            request.app.state.arq = pool
        return pool


async def list_workers(redis: Any) -> list[dict[str, Any]]:
    """Живые воркеры = непротухшие ключи metapulse:worker:* (SETEX из EventBus.heartbeat)."""
    if redis is None:
        return []
    workers: list[dict[str, Any]] = []
    try:
        async for key in redis.scan_iter(match=f"{WORKER_KEY_PREFIX}*", count=100):
            name = key.decode() if isinstance(key, bytes) else str(key)
            raw = await redis.get(name)
            ttl = await redis.ttl(name)
            state: Any = {}
            if raw:
                raw_text = raw.decode() if isinstance(raw, bytes) else str(raw)
                try:
                    state = json.loads(raw_text)
                except json.JSONDecodeError:
                    state = {"raw": raw_text}
            workers.append(
                {
                    "worker": name[len(WORKER_KEY_PREFIX) :],
                    "ttl": int(ttl) if ttl is not None else None,
                    "state": state if isinstance(state, dict) else {"value": state},
                }
            )
    except Exception as exc:  # Redis мог упасть уже после старта
        log.warning("workers_scan_failed", error=str(exc))
        return []
    return sorted(workers, key=lambda w: w["worker"])


async def build_snapshot(request: Request) -> dict[str, Any]:
    async with SessionLocal() as session:
        stats = await dashboard_stats(session)
    stats["workers"] = await list_workers(get_redis(request))
    return stats


def _is_htmx(request: Request) -> bool:
    return request.headers.get("HX-Request") == "true" and not request.headers.get(
        "HX-History-Restore-Request"
    )


# --------------------------------------------------------------------------- #
# Каталог
# --------------------------------------------------------------------------- #


async def _catalog_context(
    session: AsyncSession,
    request: Request,
    q: str,
    platform: str,
    sort: str,
    page: int,
) -> dict[str, Any]:
    games, total = await list_games(
        session, q=q, platform=platform, sort=sort, page=page, per_page=PER_PAGE
    )
    total_pages = max(1, -(-total // PER_PAGE))  # ceil
    filters = {k: v for k, v in (("q", q), ("platform", platform), ("sort", sort)) if v}
    return {
        "request": request,
        "games": games,
        "total": total,
        "page": page,
        "total_pages": total_pages,
        "q": q,
        "platform": platform,
        "sort": sort,
        # Готовая query-строка без page: пагинация не теряет фильтры и работает без JS
        "base_query": urlencode(filters),
        "has_filters": bool(filters and (q or platform)),
    }


@router.get("/", response_class=HTMLResponse, summary="Каталог игр")
async def index(
    request: Request,
    q: str = Query("", max_length=200),
    platform: str = Query("", max_length=128),
    sort: str = Query(DEFAULT := "date"),
    page: int = Query(1),
) -> HTMLResponse:
    q = q.strip()
    platform = platform.strip()
    sort = normalize_sort(sort)
    page = max(1, page)

    async with SessionLocal() as session:
        context = await _catalog_context(session, request, q, platform, sort, page)
        context["facets"] = await platform_facets(session)

    # HTMX подменяет только сетку; обычный запрос получает страницу целиком
    template = "_game_grid.html" if _is_htmx(request) else "index.html"
    return templates.TemplateResponse(request, template, context)


@router.get("/game/{slug}", response_class=HTMLResponse, summary="Карточка игры")
async def game_page(request: Request, slug: str) -> HTMLResponse:
    async with SessionLocal() as session:
        game = await get_game_by_slug(session, slug)
        if game is None:
            raise HTTPException(status_code=404, detail="Игра не найдена")
        similar = await get_similar(session, game.id)
        platforms = sorted(
            game.platforms or [],
            key=lambda p: (not p.is_lead, p.platform_name or p.platform_slug),
        )

    letsplay = game.letsplay
    # Блок летсплея бессмысленен без транскрипта — пайплайн помечает такие записи 'none'
    show_letsplay = bool(letsplay and (letsplay.transcript_source or "none") != "none")

    return templates.TemplateResponse(
        request,
        "game.html",
        {
            "request": request,
            "game": game,
            "platforms": platforms,
            "similar": similar,
            "letsplay": letsplay if show_letsplay else None,
            "critic_summary": summary_of(game, "critic"),
            "user_summary": summary_of(game, "user"),
        },
    )


# --------------------------------------------------------------------------- #
# Монитор
# --------------------------------------------------------------------------- #


@router.get("/monitor", response_class=HTMLResponse, summary="Мониторинг обработки")
async def monitor(request: Request) -> HTMLResponse:
    stats = await build_snapshot(request)
    return templates.TemplateResponse(
        request, "monitor.html", {"request": request, "stats": stats}
    )


@router.get("/api/stats", summary="Счётчики монитора")
async def api_stats(request: Request) -> JSONResponse:
    return JSONResponse(await build_snapshot(request))


async def _event_stream(request: Request) -> AsyncIterator[ServerSentEvent]:
    """События из Redis-канала + снапшот счётчиков раз в SNAPSHOT_INTERVAL_S секунд."""
    redis = get_redis(request)
    pubsub = None
    if redis is not None:
        try:
            pubsub = redis.pubsub()
            await pubsub.subscribe(EVENTS_CHANNEL)
        except Exception as exc:
            log.warning("sse_subscribe_failed", error=str(exc))
            pubsub = None

    last_snapshot = 0.0
    try:
        while True:
            if await request.is_disconnected():
                break

            now = time.monotonic()
            if now - last_snapshot >= SNAPSHOT_INTERVAL_S:
                last_snapshot = now
                try:
                    snapshot = await build_snapshot(request)
                    yield ServerSentEvent(
                        event="stats", data=json.dumps(snapshot, ensure_ascii=False, default=str)
                    )
                except Exception as exc:
                    log.warning("sse_snapshot_failed", error=str(exc))
                    yield ServerSentEvent(
                        event="error", data=json.dumps({"message": str(exc)}, ensure_ascii=False)
                    )

            if pubsub is None:
                await asyncio.sleep(1.0)
                continue

            try:
                message = await pubsub.get_message(ignore_subscribe_messages=True, timeout=1.0)
            except Exception as exc:
                log.warning("sse_pubsub_failed", error=str(exc))
                pubsub = None
                continue
            if message and message.get("type") == "message":
                data = message.get("data")
                if isinstance(data, bytes):
                    data = data.decode("utf-8", "replace")
                yield ServerSentEvent(event="task", data=str(data))
    except asyncio.CancelledError:  # клиент отвалился — сворачиваемся молча
        raise
    finally:
        if pubsub is not None:
            with contextlib.suppress(Exception):
                await pubsub.unsubscribe(EVENTS_CHANNEL)
            with contextlib.suppress(Exception):
                await pubsub.aclose()


@router.get("/api/events", summary="SSE-поток событий")
async def api_events(request: Request) -> EventSourceResponse:
    # ping шлёт comment-строки: без них прокси рвут «молчащее» соединение
    return EventSourceResponse(_event_stream(request), ping=SSE_PING_S)


@router.post("/api/admin/run", summary="Ручной запуск обработки")
async def api_admin_run(request: Request) -> JSONResponse:
    token = request.headers.get("X-Admin-Token", "")
    if not token or not secrets.compare_digest(token, settings.admin_token):
        raise HTTPException(status_code=401, detail="Неверный или отсутствующий X-Admin-Token")

    try:
        pool = await get_arq_pool(request)
        job = await pool.enqueue_job("crawl_batch", "manual")
    except HTTPException:
        raise
    except Exception as exc:
        log.error("enqueue_failed", error=str(exc))
        raise HTTPException(status_code=503, detail=f"Очередь недоступна: {exc}") from exc

    if job is None:
        # arq вернул None: задача с таким job_id уже стоит в очереди
        return JSONResponse({"status": "duplicate", "job_id": None})
    return JSONResponse({"status": "queued", "job_id": job.job_id})


# --------------------------------------------------------------------------- #
# Логи переписки с нейросетью (deliverable задания)
# --------------------------------------------------------------------------- #

# Страница собрана строковым шаблоном: список файлов в templates/ фиксирован контрактом,
# а base.html подтягивается штатным загрузчиком окружения.
LLM_LOGS_TEMPLATE = """
{% extends "base.html" %}
{% block title %}Логи LLM — MetaPulse{% endblock %}
{% block content %}
<h1 class="page-title">Логи переписки с нейросетью</h1>
<p class="muted">Каталог: <code>{{ log_dir }}</code>. Каждая строка файла — один вызов
  (запрос, ответ, usage, задержка) в формате JSONL.</p>
{% if files %}
<table class="table">
  <thead><tr><th>Файл</th><th>Строк</th><th>Размер</th><th>Изменён</th><th></th></tr></thead>
  <tbody>
  {% for f in files %}
    <tr>
      <td><a href="/llm-logs/{{ f.name }}">{{ f.name }}</a></td>
      <td class="num">{{ f.lines | int_ru }}</td>
      <td class="num">{{ f.size_kb }} КБ</td>
      <td>{{ f.mtime | date_ru }}</td>
      <td><a class="btn btn-sm" href="/llm-logs/{{ f.name }}?download=1">Скачать</a></td>
    </tr>
  {% endfor %}
  </tbody>
</table>
{% else %}
<div class="empty">
  <p>Пока ни одного файла: LLM ещё не вызывалась либо не задан ключ Anthropic.</p>
</div>
{% endif %}
{% endblock %}
"""


def _count_lines(path: Path) -> int:
    try:
        with path.open("rb") as fh:
            return sum(1 for line in fh if line.strip())
    except OSError:
        return 0


@router.get("/llm-logs", response_class=HTMLResponse, summary="Логи LLM: список файлов")
async def llm_logs(request: Request) -> HTMLResponse:
    log_dir = Path(settings.llm_log_dir)
    files: list[dict[str, Any]] = []
    if log_dir.is_dir():
        for path in sorted(log_dir.glob("*.jsonl"), reverse=True):
            stat = path.stat()
            files.append(
                {
                    "name": path.name,
                    "size_kb": round(stat.st_size / 1024, 1),
                    "lines": _count_lines(path),
                    "mtime": dt.datetime.fromtimestamp(stat.st_mtime, tz=settings.tz),
                }
            )
    html = templates.env.from_string(LLM_LOGS_TEMPLATE).render(
        request=request, files=files, log_dir=str(log_dir)
    )
    return HTMLResponse(html)


@router.get("/llm-logs/{name}", summary="Логи LLM: файл")
async def llm_log_file(name: str, download: int = 0) -> FileResponse:
    log_dir = Path(settings.llm_log_dir).resolve()
    if not LOG_NAME_RE.match(name):
        raise HTTPException(status_code=404, detail="Файл не найден")
    path = (log_dir / name).resolve()
    # Двойная защита: и проверка имени, и проверка, что путь не вылез из каталога логов
    if path.parent != log_dir or not path.is_file():
        raise HTTPException(status_code=404, detail="Файл не найден")
    headers = {"Content-Disposition": f'attachment; filename="{name}"'} if download else None
    return FileResponse(
        path,
        media_type="application/x-ndjson" if download else "text/plain; charset=utf-8",
        headers=headers,
    )

